<div class="alert alert-info d-flex flex-wrap justify-content-between align-items-center gap-2"><div><i class="bi bi-shield-check me-2"></i><strong>¿Quién puede abrir?</strong> Los permisos de residentes se definen por relación Persona ↔ Unidad.</div><?php if(can('people.view')):?><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="<?=url('people')?>">Personas y permisos</a><a class="btn btn-sm btn-outline-secondary" href="<?=url('access-profiles')?>">Perfiles</a></div><?php endif;?></div>
<div class="card"><div class="card-header d-flex justify-content-between align-items-center"><div><strong>Puntos de acceso</strong><small class="d-block text-body-secondary"><?=count($items)?> configurado(s)</small></div><?php if(can('integrations.manage')):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#accessModal"><i class="bi bi-plus-lg"></i> Nuevo punto</button><?php endif;?></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Punto</th><th>Área / equipo</th><th>Política remota</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($items as $point):?><tr id="access-<?=(int)$point['id']?>"><td><strong><?=e($point['name'])?></strong><?php if(!empty($point['resident_name'])):?><small class="d-block text-primary"><i class="bi bi-phone"></i> App: <?=e((string)$point['resident_name'])?></small><?php endif;?><small class="d-block text-body-secondary"><?=e($point['code'])?> · <?=e($point['access_type'])?></small></td><td><?php if(!empty($point['property_id'])):?><a href="<?=url('structure-context',['id'=>$point['property_id']])?>"><i class="bi bi-geo-alt"></i> <?=e($point['property_name']?:'Ubicación estructural')?></a><?php else:?><span class="text-body-secondary">General</span><?php endif;?><?php if(!empty($point['area_id'])):?><small class="d-block"><a href="<?=url('area-context',['id'=>$point['area_id']])?>"><i class="bi bi-bounding-box"></i> <?=e($point['area'])?></a></small><?php endif;?><?php if(!empty($point['side_a_label'])||!empty($point['side_b_label'])):?><small class="d-block text-body-secondary"><i class="bi bi-arrow-left-right"></i> <?=e($point['side_a_label']?:'Lado A')?> ↔ <?=e($point['side_b_label']?:'Lado B')?></small><?php endif;?><small class="d-block text-body-secondary"><?=e($point['device_name']?:$point['connector']?:'Sin equipo directo; usar Mapeo físico')?></small><?php $linkedCameraCount=count((array)($point['camera_ids']??[]));if($linkedCameraCount):?><small class="d-block text-success"><i class="bi bi-camera-video me-1"></i><?=$linkedCameraCount?> cámara(s) asociada(s)</small><?php endif;?></td><td><?=e($point['remote_policy'])?></td><td><span class="badge text-bg-<?=e(status_badge((string)$point['status']))?>"><?=e(status_label((string)$point['status']))?></span></td><td class="text-end"><?php if(can('integrations.manage')):?><button class="btn btn-sm btn-outline-primary js-edit-access" data-bs-toggle="modal" data-bs-target="#accessModal" data-json='<?=e(json_encode($point,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-pencil"></i></button> <form class="d-inline" method="post" action="<?=url('access-point-delete')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$point['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="¿Eliminar este punto de acceso?"><i class="bi bi-trash"></i></button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5" class="text-center text-body-secondary py-4">No hay puntos de acceso configurados.</td></tr><?php endif;?></tbody></table></div></div></div>
<?php if(can('integrations.manage')):?><div class="modal fade" id="accessModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form method="post" action="<?=url('access-point-save')?>"><?=csrf_field()?><input type="hidden" name="id" id="accessId"><div class="modal-header"><h5 class="modal-title">Punto de acceso</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-4"><label class="form-label">Código</label><input class="form-control" name="code" id="accessCode" required></div><div class="col-md-4"><label class="form-label">Nombre administrativo</label><input class="form-control" name="name" id="accessName" required></div><div class="col-md-4"><label class="form-label">Nombre para residentes</label><input class="form-control" name="resident_name" id="accessResidentName" placeholder="Ej. Portón principal"></div><div class="col-md-2"><label class="form-label">Orden</label><input class="form-control" type="number" min="0" max="9999" name="display_order" id="accessDisplayOrder" value="100"></div><div class="col-md-4"><label class="form-label">Tipo</label><select class="form-select" name="access_type" id="accessType"><?php foreach(['door'=>'Puerta','gate'=>'Portón','turnstile'=>'Torniquete','elevator'=>'Ascensor','barrier'=>'Barrera','lock'=>'Cerradura','relay'=>'Relé','other'=>'Otro'] as $v=>$l):?><option value="<?=e($v)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Operación</label><select class="form-select" name="operation_mode" id="accessOperation"><option value="credential">Credencial</option><option value="remote">Remota</option><option value="hybrid">Híbrida</option><option value="manual">Manual</option></select></div><div class="col-md-4"><label class="form-label">Estado</label><select class="form-select" name="status" id="accessStatus"><option value="active">Activo</option><option value="maintenance">Mantenimiento</option><option value="disabled">Deshabilitado</option></select></div><div class="col-md-6"><label class="form-label">Ubicación estructural</label><select class="form-select" name="property_id" id="accessProperty"><option value="">General</option><?php foreach($properties as $p):?><option value="<?=$p['id']?>"><?=e((string)($p['label']??$p['name']))?> · <?=e(property_type_label((string)$p['property_type']))?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Área / espacio específico <span class="text-body-secondary">(opcional)</span></label><select class="form-select" name="area_id" id="accessArea"><option value="">Sin área específica</option><?php foreach($areas as $a):?><option value="<?=$a['id']?>" data-property-id="<?=e($a['property_id']??'')?>"><?=e($a['name'])?> · <?=e(area_scope_label((string)($a['scope_type']??'common')))?> · <?=e(area_usage_label((string)($a['usage_type']??'general')))?></option><?php endforeach;?></select><div class="form-text" id="accessAreaHelp">Selecciona primero la ubicación estructural.</div></div><div class="col-md-6"><label class="form-label">Equipo directo (compatibilidad)</label><select class="form-select" name="device_id" id="accessDevice"><option value="">Sin equipo directo; usar Mapeo físico</option><?php foreach($devices as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?> · <?=e($d['device_type'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Política remota</label><select class="form-select" name="remote_policy" id="accessPolicy"><option value="disabled">No visible en app</option><option value="local_only">Solo red local</option><option value="allowed">Permitida</option><option value="second_factor">Segundo factor</option><option value="approval_required">Requiere aprobación</option></select></div><div class="col-12"><label class="form-label"><i class="bi bi-camera-video me-1"></i>Cámaras asociadas a este acceso</label><select class="form-select" name="camera_ids[]" id="accessCameras" multiple size="<?=min(7,max(3,count($cameras)))?>"><?php foreach($cameras as $cam):?><option value="<?=e($cam['id'])?>"><?=e((string)($cam['name']??'Cámara'))?><?php if(!empty($cam['area'])||!empty($cam['property_name'])):?> · <?=e((string)($cam['area']?:$cam['property_name']))?><?php endif;?></option><?php endforeach;?></select><div class="form-text">La misma relación se puede administrar desde la cámara. Cuando un operador vea una cámara asociada podrá abrir este acceso sin cerrar el video, si sus permisos y la ruta remota lo permiten.</div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div></form></div></div></div><script>
document.addEventListener('DOMContentLoaded',()=>{
  const modal=document.getElementById('accessModal');if(!modal)return;
  const prop=document.getElementById('accessProperty'),area=document.getElementById('accessArea');
  const filterAreas=(keep='')=>{const pid=String(prop.value||'');let visible=0;[...area.options].forEach((o,i)=>{if(i===0){o.hidden=false;o.disabled=false;return;}const ok=pid!==''&&String(o.dataset.propertyId||'')===pid;o.hidden=!ok;o.disabled=!ok;if(ok)visible++;});if(keep){const wanted=[...area.options].find(o=>String(o.value)===String(keep)&&!o.disabled);area.value=wanted?String(keep):'';}else if(area.selectedOptions[0]?.disabled)area.value='';const h=document.getElementById('accessAreaHelp');if(h)h.textContent=pid===''?'Selecciona primero la ubicación estructural.':(visible?`${visible} área(s) disponible(s) en esta ubicación.`:'No hay áreas aquí; el acceso puede quedar directamente en la estructura.');};
  modal.addEventListener('show.bs.modal',e=>{let d={};try{d=JSON.parse(e.relatedTarget?.dataset.json||'{}')}catch(x){};for(const [id,key,def] of [['accessId','id',''],['accessCode','code',''],['accessName','name',''],['accessResidentName','resident_name',''],['accessDisplayOrder','display_order','100'],['accessType','access_type','door'],['accessOperation','operation_mode','hybrid'],['accessStatus','status','active'],['accessProperty','property_id',''],['accessArea','area_id',''],['accessDevice','device_id',''],['accessPolicy','remote_policy','disabled']])document.getElementById(id).value=d[key]??def;filterAreas(d.area_id||'');const linked=new Set((d.camera_ids||[]).map(Number));const sel=document.getElementById('accessCameras');if(sel)Array.from(sel.options).forEach(o=>o.selected=linked.has(Number(o.value)));});
  prop.addEventListener('change',filterAreas);
  if(<?= !empty($_GET['new'])?'true':'false' ?>){prop.value='<?= (int)($_GET['property_id']??0) ?>';filterAreas();area.value='<?= (int)($_GET['area_id']??0) ?>';bootstrap.Modal.getOrCreateInstance(modal).show();}
});
</script><?php endif;?>
